% this is some matlab code i wrote to illustrate 
% the use of the rearrangement inequality in finding the 
% key length of vigenere ciphers. 
% 
% to run it, just save it as findlength.m , and then 
% just say findlength (assuming you're running matlab 
% in the directory containing this code, with the correct 
% file name)... 

% this is the full text of raymond t. chandler's ``the big sleep''...
plain=[''];

nums=double(plain)-97; % convert text to a vector of numbers in Z/26Z
len=size(nums,2);      % compute the # of entries in the vector

% let's first check the letter frequencies in our plain-text... 
count=0; freq=zeros(1,26);
% for i=2:10:len
for i=1:len
 freq(nums(i)+1)=freq(nums(i)+1)+1;
 count=count+1; 
end;

% print out frequency data: table from book vs. what we observe 
% for chandler's novel...
count 
freq=freq/count; 
[y ind]=sort(freq);
         mostfreq=['etaoinshr']
char(ind([26:-1:18])+96) 
% turns out to be: 'etaoihnsd' . so top 5 agree...

% now let's set up a vigenere cipher...
key=[21 23 3 23 16 2 7 14 24 25 4 25 24]; % via matlab's floor(rand(1,13)*26)

% the numbers for the cipher-text...
cnums=zeros(1,266071);
for i=0:13:266058 % step by 13s 
 for j=1:13 
  cnums(i+j)=mod(nums(i+j)+key(j),26); 
 end; 
end; 

% the text you would see if you converted to letters...
cipher=char(cnums+97); 

% now let's count collisions! 
freq=zeros(1,40); 
for i=1:40
 count=0; slen=266071-i-1; 
 for j=1:slen 
  if cnums(j+i)==cnums(j) 
   count=count+1; 
  end; 
 end; 
 freq(i)=count/slen; 
end;  
[y,i]=sort(freq)  

% looks like 13, 26, and 39 sang right out!!! : ) 
% now let's try 13 and see who is most frequent... 
mostlikely=zeros(1,13); 
for j=1:13 
 count=zeros(1,26); 
 for i=0:13:266058 % step by 13s
  count(cnums(i+j)+1)=count(cnums(i+j)+1)+1;  
 end; 
 [y,ind]=max(count); 
 char(ind+96)
 mostlikely(j)=mod(ind-5,26); 
end; 

mostlikely 
